   {
    "heading": "Step-by-step guides",
    "items": [
     {
      "type": "howto",
      "title": "Creating and checking hard links / symbolic links",
      "steps": [
       {
        "text": "Create the original file",
        "command": "echo \"hello\" > original.txt"
       },
       {
        "text": "Create a hard link pointing to the same inode",
        "command": "ln original.txt hardlink.txt"
       },
       {
        "text": "Create a symbolic link pointing to the original file's path",
        "command": "ln -s original.txt softlink.txt"
       },
       {
        "text": "Check whether both point to the same inode",
        "command": "ls -li original.txt hardlink.txt softlink.txt"
       },
       {
        "text": "Delete the original file; the hard link still has the data, the symlink breaks",
        "command": "rm original.txt && cat hardlink.txt; cat softlink.txt"
       }
      ]
     }
    ]
   }
